package com.tecsup.cita.controller;import com.tecsup.cita.dto.*;import com.tecsup.cita.model.*;import com.tecsup.cita.service.CitaService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/citas")public class CitaController{private final CitaService s;public CitaController(CitaService s){this.s=s;}@GetMapping public List<Cita>listar(){return s.listar();}@GetMapping("/{id}")public Cita obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Cita crear(@Valid@RequestBody CitaRequest d){return s.crear(d);}@PutMapping("/{id}/estado")public Cita estado(@PathVariable Long id,@Valid@RequestBody EstadoRequest d){return s.actualizarEstado(id,d.estado());}@PostMapping("/{id}/cancelar")public Cita cancelar(@PathVariable Long id){return s.cancelar(id);}@PostMapping("/{id}/atencion")public Atencion atencion(@PathVariable Long id,@Valid@RequestBody CitaService.AtencionRequest d){return s.registrarAtencion(id,d);}@GetMapping("/{id}/atencion")public Atencion obtenerAtencion(@PathVariable Long id){return s.obtenerAtencion(id);}}
